use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Types implementing this trait can be parsed from a positional numeral system with radix 10."] # [doc = " Acts much like `FromRadix10`, but performs additional checks for overflows."] pub trait FromRadix10Checked : FromRadix10 { # [doc = " Parses an integer from a slice."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use atoi::FromRadix10Checked;"] # [doc = " // Parsing to digits from a slice"] # [doc = " assert_eq!((Some(42),2), u32::from_radix_10_checked(b\"42\"));"] # [doc = " // Additional bytes after the number are ignored"] # [doc = " assert_eq!((Some(42),2), u32::from_radix_10_checked(b\"42 is the answer to life, the universe and everything\"));"] # [doc = " // (0,0) is returned if the slice does not start with a digit"] # [doc = " assert_eq!((Some(0),0), u32::from_radix_10_checked(b\"Sadly we do not know the question\"));"] # [doc = " // While signed integer types are supported..."] # [doc = " assert_eq!((Some(42),2), i32::from_radix_10_checked(b\"42\"));"] # [doc = " // Signs are not allowed (even for signed integer types)"] # [doc = " assert_eq!((Some(0),0), i32::from_radix_10_checked(b\"-42\"));"] # [doc = " // Leading zeros are allowed"] # [doc = " assert_eq!((Some(42),4), u32::from_radix_10_checked(b\"0042\"));"] # [doc = " // Overflow is indicated by `None`"] # [doc = " assert_eq!((None, 3), u8::from_radix_10_checked(b\"256\"));"] # [doc = " ```"] # [doc = ""] # [doc = " # Return"] # [doc = ""] # [doc = " Returns a tuple with two numbers. The first is the integer parsed or zero if no digit has"] # [doc = " been found. None, if there were too many, or too high dighits and the parsing overflowed."] # [doc = " The second is the index of the byte right after the parsed number. If the second element is"] # [doc = " zero the slice did not start with an ASCII digit."] fn from_radix_10_checked (_ : & [u8]) -> (Option < Self > , usize) ; }